function card(t){return `<article class="track"><div class="track-top"><button class="identity" data-detail="${esc(t.id)}"><span class="artist">${esc(t.artistName)}</span><h3>${esc(t.title)}</h3></button><div class="score">${t.score}<small>/ 100</small></div></div><span class="track-meta">${esc(trackMeta(t))}</span>${releaseTags(t)}<p class="reason">${esc(t.reason)}</p><div class="track-bottom">${auditionControl(t,'card:'+t.id)}${statusFlags(t)}${boardActions(t)}</div></article>`}
function priority(t,i){return `<article class="priority-row"><span class="rank">0${i+1}</span><button class="identity" data-detail="${esc(t.id)}"><strong>${esc(t.title)}</strong><span class="artist">${esc(t.artistName)} · ${esc(lanes[t.lane].split(' / ')[0])}</span></button><div class="score">${t.score}<small>${t.confidence}% CONF.</small></div><p class="reason">${esc(t.reason)}</p>${auditionControl(t,'priority:'+t.id)}${statusFlags(t)}${boardActions(t)}</article>`}
function meter(label,value,desc){return `<div class="meter"><label>${label}<b>${desc??value+'%'}</b></label><div class="bar"><i style="width:${value}%"></i></div></div>`}
function module(m,ts,drop){const dropMixes=feedState.source==='github'?getDropMixes(drop.id):mixes;let title='',body='',cls='',sub='';if(m.id==='start'){title='<svg class="top3-arrow" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M4 16 16 4M7 4h9v9"/></svg><span>Top 3</span>';sub='Top Picks: from the drop';cls='priority';body=`<div class="panel-body">${ts.slice(0,3).map(priority).join('')||'<p>No visible tracks. Restore hidden tracks below.</p>'}</div>`}else if(m.id==='signal'){title='<span class="signal-icon" aria-hidden="true"><i></i></span><span>Weekly signal</span>';sub='THE SHAPE OF THIS DROP';cls='signal-panel';const p=activeProfile();let counts=lanes.map((_,i)=>ts.filter(t=>t.lane===i).length);body=`<div class="signal"><div class="stats"><div><strong>${String(ts.length).padStart(2,'0')}</strong><span>TRACKS SELECTED</span></div><div><strong>${String(feedState.source==='github'?dropMixes.length:(p.mixes?1:0)).padStart(2,'0')}</strong><span>DJ MIXES</span></div></div><div class="distribution">${counts.map(c=>`<span style="flex:${c}"></span>`).join('')}</div><div class="lane-key">${counts.slice(0,3).map((c,i)=>`<span><span class="marker m${i}" aria-hidden="true"></span>${['Future','Deep','Jungle'][i]} ${c}</span>`).join('')}</div>${meter('Discovery depth',p.depth,p.depth>65?'Deep dig':'Familiar ground')}${meter('Experimental bias',p.experimental)}${meter('Floor ↔ headphones',p.floor,p.floor+'% headphones')}<p class="signal-foot">${getFeedProfile(selectedDrop()?.id)?`Published profile snapshot · ${getFeedProfile(selectedDrop()?.id).source==='weeklyOverride'?'This week override':'Base profile'}`:`Your local profile · ${profiles.weekly?.week===drops[0].id?'This week override':'Base preferences'}`}</p></div>` }else if(m.id==='mix'){if(!dropMixes.length)return '';title='DJ mix crate';sub=String(dropMixes.length).padStart(2,'0')+' SESSIONS';body=`<div class="mix-stack">${dropMixes.map(mx=>{const embedded=embedPreview(mx);return `<div class="mix"><div class="mix-icon">◉</div><div class="mix-copy"><span class="artist">${esc(mx.artistName)}</span><strong>${esc(mx.title)}</strong><span class="track-meta">${esc(mx.reason||'Published weekly mix')}</span>${destinationActions(mx,false)}</div>${buttons(mx)}</div>${embedded?providerShell(mx,embedded,'mix:'+mx.id,'mix-provider'):''}`}).join('')}</div>`}else{let i=Number(m.id.slice(-1));let list=ts.filter(t=>t.lane===i);if(!list.length)return '';title=`<span class="marker m${i}"></span>${lanes[i]}`;sub=String(list.length).padStart(2,'0')+' TRACKS';body=`<div class="bin-grid">${list.map(card).join('')}</div>`}const sizes=m.id==='signal'?['compact','standard']:m.id==='start'||m.id==='mix'?['standard','wide']:['wide'];return `<section class="panel ${m.size} ${cls}" data-module="${m.id}">${editing?`<div class="module-controls"><button draggable="true" data-drag="${m.id}" aria-label="Drag ${m.id} module">⠿ Move</button><button data-move="-1" data-module-id="${m.id}" aria-label="Move ${m.id} up">↑</button><button data-move="1" data-module-id="${m.id}" aria-label="Move ${m.id} down">↓</button><label>Size <select data-size="${m.id}">${sizes.map(s=>`<option ${s===m.size?'selected':''}>${s}</option>`).join('')}</select></label></div>`:''}<div class="panel-head"><h2>${title}</h2><small>${sub}</small></div>${body}</section>`}
function header(title,sub,drop){
  const live=feedState.source==='github',test=live&&drop?.id?.startsWith('TEST-');
  const schedule=scheduleState.data,next=scheduleState.status==='ready'?formatNextDrop(schedule):scheduleLabel();
  const overridden=!!schedule?.override;
  return `<div class="drop-heading"><div><div class="eyebrow">${drop?'WEEKLY TRANSMISSION / '+drop.period:'YOUR PERSONAL CRATE'}</div><h1>${title}</h1><p>${sub}</p></div><div class="drop-heading-meta"><span class="seed">${live?(test?'TEST DROP · LIVE FEED':'LIVE FEED · GITHUB'):'PHASE 1 · DEMO FALLBACK'}</span><span class="next-drop-flag ${overridden?'is-override':''}"><small>${esc(scheduleLabel())}</small><b>${esc(next)}</b>${overridden?'<i>SCHEDULE OVERRIDE</i>':''}<em class="pipeline-flag ${pipelineState.status==='staged'?'is-ready':''}">${esc(preflightLabel(schedule?.nextDropAt))}</em></span></div></div>`}
function render(){let path=location.pathname.replace(/\/$/,'')||'/';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.route==='/'?path==='/':path.startsWith(a.dataset.route)));$('#saved-count').textContent=Object.values(interactions).filter(i=>i.saved).length;const mobile=matchMedia('(max-width:700px)').matches;$('#edit').textContent=(mobile?mobileEditing:editing)?'✓ DONE':'⊞ EDIT LAYOUT';$('#edit').setAttribute('aria-expanded',String(mobile?mobileEditing:editing));$('#edit').hidden=path==='/archive'||path==='/saved'||(mobile&&path!=='/');let html='';if(path==='/archive'){html=header('The archive','Previous transmissions. Good music doesn’t expire.')+`<div class="archive-list">${drops.slice(1).map(d=>`<a class="archive-card" href="/archive/${d.id}"><span class="eyebrow">${d.period}</span><h2>Drop ${d.id} <span class="cyan">↗</span></h2><p>${d.ids.length} tracks · Published collection</p><span class="track-meta">OPEN THIS DROP</span></a>`).join('')}</div>`}else if(path==='/saved'){let ts=tracks.filter(t=>interactions[t.id]?.saved&&!interactions[t.id]?.hidden);let ms=mixes.filter(t=>interactions[t.id]?.saved);html=header('Saved for later','Your selections, ready for another listen.')+`<div class="filters">${['all','tracks','mixes'].map(f=>`<button data-filter="${f}" class="${f===filter?'active':''}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div>`;let items=(filter!=='mixes'?ts.map(card).join(''):'')+(filter!=='tracks'?ms.map(m=>`<article class="track"><span class="artist">${m.artistName}</span><h3>${m.title}</h3><p>${m.reason}</p>${buttons(m)}</article>`).join(''):'');html+=items?`<section class="panel wide"><div class="bin-grid">${items}</div></section>`:'<div class="panel empty"><h2>Your next favorite belongs here.</h2><p>Save a track or mix from This Week to start your crate.</p><a href="/" class="cyan">Explore this week ↗</a></div>'}else{let d=path.startsWith('/archive/')?drops.find(d=>d.id===path.split('/')[2]):drops[0];if(!d){html='<div class="empty"><h1>Drop not found</h1><a href="/archive">Back to archive</a></div>'}else{let ts=d.ids.map(id=>tracks.find(t=>t.id===id)).filter(t=>t&&!interactions[t.id]?.hidden);html=(d===drops[0]?heroMarkup()+(mobileEditing?'<div class="mobile-layout-editor"><span>HERO GRADIENT</span>'+paletteMarkup()+'</div>':''):'')+header(`${d===drops[0]?'This week’s drop':'Archived drop'} <span>/ ${d.id}</span>`,'A little further underground. Start with three, dig into the rest.',d)+(editing?'<div class="editbar"><span>Move modules using handles or ↑ ↓. Changes save automatically.</span><button id="reset-layout">Reset layout</button></div>':'')+`<div class="grid ${editing?'editing':''}">${layout.map(m=>module(m,ts,d)).join('')}</div>`;if(d.ids.some(id=>interactions[id]?.hidden))html+='<p><button id="restore">Restore hidden tracks</button></p>'}}html+=`<p class="footer-note">${feedState.source==='github'?'LIVE WEEKLY FEED · Published recommendations are loaded from the versioned DROP:PORTAL GitHub feed.':'DEMO FALLBACK · Illustrative artists, titles, scores and mixes. Three original synthesized preview studies.'}<br>Preview availability is source-dependent. Saved and Heard stay in this browser. Tuner settings sync with the publisher.</p>`;$('#app').innerHTML=html;$('#palette-controls').innerHTML=path==='/'?paletteMarkup():'';initHero();updatePlayer()}
function route(path){stopProviderPlayback();history.pushState({},'',path);editing=false;mobileEditing=false;render();window.scrollTo(0,0)}document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!e.ctrlKey&&!e.metaKey){e.preventDefault();route(a.pathname);return}const b=e.target.closest('button');if(!b)return;if(b.dataset.providerActivate){dockCollapsed=false;if(player.current)player.stop();activeProviderSlot=b.dataset.providerActivate;providerDockSlot=null;render();return}if(b.dataset.providerFocus){document.querySelector(`[data-provider-slot="${CSS.escape(b.dataset.providerFocus)}"]`)?.scrollIntoView({behavior:'smooth',block:'center'});return}if(b.dataset.providerUnload){stopProviderPlayback();render();return}if(b.dataset.play){dockCollapsed=false;stopProviderPlayback();render();player.play(tracks.find(t=>t.id===b.dataset.play));return}if(b.dataset.detail){detail(b.dataset.detail);return}if(b.dataset.action){act(b.dataset.id,b.dataset.action);return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.move){move(b.dataset.moduleId,Number(b.dataset.move));return}if(b.dataset.close){$('#'+b.dataset.close).close();if(b.dataset.close==='detail')detailId=null;return}if(b.id==='edit'){if(matchMedia('(max-width:700px)').matches)mobileEditing=!mobileEditing;else editing=!editing;render();return}if(b.id==='reset-layout'){layout=JSON.parse(JSON.stringify(defaultLayout));persist('layout',layout);render();toast('Default layout restored')}if(b.id==='restore'){interactions=mergeInteractions(interactions,read('interactions',{}));for(const id of selectedDrop()?.ids||[])if(interactions[id]?.hidden)interactions=updateInteraction(interactions,id,'hidden',false);persist('interactions',interactions);render()}if(b.id==='tuner'){openTuner();return}if(b.id==='dock-close'||b.classList.contains('provider-native-close')){dockCollapsed=true;updatePlayer();return}if(b.id==='dock-restore'){dockCollapsed=false;updatePlayer();return}});
function move(id,delta){let i=layout.findIndex(m=>m.id===id),j=i+delta;if(j<0||j>=layout.length)return;[layout[i],layout[j]]=[layout[j],layout[i]];persist('layout',layout);render();toast('Module moved')}
document.addEventListener('change',e=>{if(e.target.dataset.size){layout.find(m=>m.id===e.target.dataset.size).size=e.target.value;persist('layout',layout);render()}});document.addEventListener('dragstart',e=>{let handle=e.target.closest('[data-drag]');if(!editing||!handle)return;dragged=handle.dataset.drag;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move'});document.addEventListener('dragover',e=>{if(editing&&dragged&&e.target.closest('[data-module]'))e.preventDefault()});document.addEventListener('drop',e=>{let target=e.target.closest('[data-module]');if(!editing||!dragged||!target)return;e.preventDefault();let i=layout.findIndex(m=>m.id===dragged),j=layout.findIndex(m=>m.id===target.dataset.module);let[m]=layout.splice(i,1);layout.splice(j,0,m);dragged=null;persist('layout',layout);render()});document.addEventListener('dragend',()=>dragged=null);
function detail(id,show=true){let t=tracks.find(t=>t.id===id);if(!t)return;detailId=id;const live=feedState.source==='github'&&!t.demo;const releaseInfo=live?`<div class="release-facts"><span><small>RELEASE</small>${esc(t.release||'Not supplied')}</span><span><small>LABEL</small>${esc(t.label||'Not supplied')}</span><span><small>DATE</small>${esc(formatReleaseDate(t.releaseDate)||'Not supplied')}</span><span><small>STYLE</small>${esc(t.subgenre||lanes[t.lane])}</span></div>${destinationActions(t,false,false,'track:'+t.id,true)}<div class="source-list">${sourceLinks(t)||'<span class="availability">NO VERIFIED SOURCE SUPPLIED</span>'}</div>`:'<p class="notice">Prototype entry. Artist, title and grading are illustrative. Release date, label and purchase links have not been supplied.</p>';$('#detail').innerHTML=`<div class="drawer-head"><span>TRACK DETAIL / ${live?'LIVE FEED':'DEMO'}</span><button data-close="detail" aria-label="Close track detail">✕</button></div><span class="artist">${esc(t.artistName)}</span><h2>${esc(t.title)}</h2><span class="track-meta">${esc([lanes[t.lane],Number.isFinite(t.bpm)?t.bpm+' BPM':null].filter(Boolean).join(' · '))}</span><h3>WHY IT’S HERE</h3><p>${esc(t.reason)}</p><h3>${live?'CURATION GRADING':'ILLUSTRATIVE GRADING'}</h3>${Object.entries(t.scores||{}).map(([k,v])=>`<div class="metric-row"><span>${esc(k[0].toUpperCase()+k.slice(1))}</span><b>${Number(v)} / 100</b></div>`).join('')}<div class="metric-row"><span>Overall / subgenre confidence</span><b>${t.score} / ${t.confidence}%</b></div><h3>RELEASE & DESTINATIONS</h3>${releaseInfo}<h3>YOUR CRATE</h3>${buttons(t)}<p><button data-action="hidden" data-id="${esc(t.id)}">Hide this track</button></p>`;if(show&&!$('#detail').open)$('#detail').showModal();updatePlayer()}
document.addEventListener('input',e=>{if(e.target.matches('[data-seek]'))player.seek(Number(e.target.value));if(e.target.id==='volume')player.audio.volume=Number(e.target.value)});
function waveHTML(){return player.waveform()+`<input data-seek type="range" min="0" max="${player.audio.duration||16}" step="0.05" value="${player.audio.currentTime}" aria-label="Seek preview">`}
const providerDockBars=[10,17,24,14,29,20,12,25,18,30,16,23,12,27,19,14,26,21,11,24,17,29,15,22];
function providerDockWave(){return `<div class="provider-dock-wave" role="img" aria-label="Ambient animation; audio controlled in Bandcamp">${Array.from({length:80},(_,i)=>`<i style="height:${providerDockBars[(i*7)%providerDockBars.length]}px;--pulse:${(.6+(i*13%47)/50).toFixed(2)}s;--offset:-${(i*.173%2).toFixed(2)}s"></i>`).join('')}</div>`}
let dockId=null;function updatePlayer(){
  const dock=$('#dock'),restore=$('#dock-restore'),t=player.current,providerItem=providerDockItem();restore.hidden=!(dockCollapsed&&(t||providerItem));restore.textContent=(providerItem&&!t?'▲  '+providerItem.title:'▲  PLAYER');dock.hidden=!!dockCollapsed||!(t||providerItem);
  document.querySelectorAll('[data-play]').forEach(b=>{const on=t?.id===b.dataset.play&&player.status==='playing';b.textContent=on?'Ⅱ':'▶';b.setAttribute('aria-label',(on?'Pause ':'Play ')+tracks.find(t=>t.id===b.dataset.play)?.title)});
  if(!t&&providerItem){
    const provider=providerItem.preview?.provider||'BANDCAMP';
    dock.innerHTML=`<div class="dock-inner provider-native-dock"><div class="dock-title"><button data-provider-focus="${esc(providerDockSlot)}"><strong>${esc(providerItem.title)}</strong><small>${esc(providerItem.artistName)} · ${esc(provider)} STREAM</small></button></div><button class="provider-native-close" aria-label="Minimize provider player">✕</button><div class="provider-native-controls is-provider-locked" aria-label="Bandcamp transport unavailable in native dock"><button class="provider-native-skip" disabled aria-label="Previous track unavailable while Bandcamp controls playback">←</button><button class="provider-native-play" disabled aria-label="Play unavailable while Bandcamp controls playback">▶</button><button class="provider-native-skip" disabled aria-label="Next track unavailable while Bandcamp controls playback">→</button></div>${providerDockWave()}<span class="provider-control-note">CONTROL IN EMBED</span></div>`;
    dockId='provider:'+providerItem.id;
    return;
  }
  if(!t){dockId=null;return}
  if(dockId!==t.id){
    dock.innerHTML=`<div class="dock-inner"><div class="dock-title"><button data-detail="${esc(t.id)}"><strong>${esc(t.title)}</strong><small>${esc(t.artistName)} · ${esc(t.preview?.provider||'AUTHORIZED PREVIEW')}</small></button></div>${playButton(t)}<div class="wave" id="dock-wave"></div><span class="timing" id="dock-time"></span><input id="volume" class="volume" type="range" min="0" max="1" step=".01" value="${player.audio.volume}" aria-label="Preview volume"><button id="dock-close" aria-label="Minimize preview player">✕</button></div>`;
    dockId=t.id;
  }
  const timing=player.status==='error'?'Preview failed · tap play to retry':player.status==='loading'?'Loading…':`${player.time(player.audio.currentTime)} / ${player.time(player.audio.duration||16)}`;
  $('#dock-time').textContent=timing;updateWave($('#dock-wave'));$('#dock [data-play]').textContent=player.status==='playing'?'Ⅱ':'▶';$('#dock [data-play]').setAttribute('aria-label',(player.status==='playing'?'Pause ':'Play ')+t.title);if(detailId===t.id&&$('#detail-wave')){updateWave($('#detail-wave'));$('#detail-time').textContent=timing}
}
function updateWave(el){if(!el)return;const focused=el.contains(document.activeElement);if(focused){const svg=el.querySelector('svg');if(svg){const temp=document.createElement('div');temp.innerHTML=player.waveform();svg.replaceWith(temp.firstElementChild)}}else el.innerHTML=waveHTML()}
window.addEventListener('previewchange',updatePlayer);window.addEventListener('popstate',()=>{stopProviderPlayback();editing=false;mobileEditing=false;render()});/* interaction state is written only on explicit user actions; avoid destructive pagehide rewrites */for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d&&e.clientX<d.getBoundingClientRect().left)d.close()});$('#detail').addEventListener('close',()=>detailId=null);setupTuner({toast,onSaved:()=>{updateScheduleFlag();loadPipelineStatus().then(updateScheduleFlag);}});
const feedNotice=document.createElement('div');feedNotice.className='feed-update';feedNotice.hidden=true;feedNotice.setAttribute('role','status');document.querySelector('header').after(feedNotice);
function updateScheduleFlag(){document.querySelectorAll('.next-drop-flag').forEach(el=>{el.querySelector('small').textContent=scheduleLabel();el.querySelector('b').textContent=scheduleState.status==='ready'?formatNextDrop():scheduleLabel();el.classList.toggle('is-override',!!scheduleState.data?.override);const preflight=el.querySelector('.pipeline-flag');if(preflight){preflight.textContent=preflightLabel(scheduleState.data?.nextDropAt);preflight.classList.toggle('is-ready',pipelineState.status==='staged'&&pipelineState.scheduledAt===scheduleState.data?.nextDropAt);}const old=el.querySelector('i');if(old)old.remove();if(scheduleState.data?.override){const note=document.createElement('i');note.textContent='SCHEDULE OVERRIDE';el.append(note);}});}
const refresh=createFeedRefresh({
  canApply:()=>!activeProviderSlot&&!editing&&!document.querySelector('dialog[open]'),
  onApplied:()=>{render();toast('New drop loaded');},
  onPending:pending=>{feedNotice.hidden=!pending;feedNotice.textContent=pending?'A new drop is ready. It will appear after you finish the current preview or close your editor.':'';},
  onError:()=>{feedNotice.hidden=false;feedNotice.textContent='Could not check for a newer drop. Your current crate is still available.';}
});
let refreshBusy=false;
async function refreshAll(){if(document.hidden||refreshBusy)return;refreshBusy=true;try{await Promise.all([refresh.check(),document.querySelector('#tuner-dialog').open?Promise.resolve():loadSchedule().then(updateScheduleFlag),loadPipelineStatus().then(updateScheduleFlag)]);}finally{refreshBusy=false;}}
window.addEventListener('focus',refreshAll);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshAll();});
window.setInterval(refreshAll,60000);
for(const d of document.querySelectorAll('dialog'))d.addEventListener('close',()=>refresh.flush());
document.addEventListener('click',()=>queueMicrotask(()=>refresh.flush()));
render();Promise.all([loadWeeklyFeed(),loadSchedule(),loadPipelineStatus()]).then(([feedOk])=>{render();if(feedOk)toast('Weekly drop synced');});

window.addEventListener('storage',event=>{
  if(event.key!=='drop-portal:interactions')return;
  const incoming=read('interactions',{}),merged=mergeInteractions(interactions,incoming);
  if(JSON.stringify(merged)===JSON.stringify(interactions))return;
  interactions=merged;if(JSON.stringify(merged)!==JSON.stringify(incoming))write('interactions',merged);
  if(!activeProviderSlot&&!editing){render();if(detailId)detail(detailId,false);}
  else $('#saved-count').textContent=Object.values(interactions).filter(i=>i.saved).length;
});
